function rotate(nums, k) {
  const n = nums.length;
  k = ((k % n) + n) % n;
  const reverse = (l, r) => {
    while (l < r) {
      const t = nums[l];
      nums[l] = nums[r];
      nums[r] = t;
      l += 1;
      r -= 1;
    }
  };
  reverse(0, n - 1);
  reverse(0, k - 1);
  reverse(k, n - 1);
}

function reverseList(head) {
  let prev = null;
  let cur = head;
  while (cur) {
    const next = cur.next;
    cur.next = prev;
    prev = cur;
    cur = next;
  }
  return prev;
}

function invertTree(root) {
  if (!root) return null;
  const left = invertTree(root.left);
  const right = invertTree(root.right);
  root.left = right;
  root.right = left;
  return root;
}

